-- ATLAS Codex: all remaining generated Quant figures.
-- Paste into the Supabase SQL editor and run. Idempotent.

on conflict (fig_id) do nothing;

-- verify: expect 33 rows, all origin='generated'
select count(*) as figures, count(*) filter (where origin='generated') as generated,
       count(distinct split_part(fig_id,'.',2)) as modules_covered
from codex_figures;
