insert into codex_figures (fig_id,topic_id,title,alt,view_box,svg,caption,los_refs,origin) values
('QM.LM1.01','quant','The regression process','Flow from specifying a model, estimating it, checking residuals, testing fit, to using it, with a feedback loop from residual checks back to specification.','0 0 700 160','<rect class="node-c" x="14" y="48" width="96" height="36" rx="2"/><text class="nt" x="62" y="64" text-anchor="middle">Specify</text><text class="nm" x="62" y="76" text-anchor="middle">economic reasoning</text><path class="edge" d="M110 66 H146" marker-end="url(#a)"/><rect class="node" x="146" y="48" width="96" height="36" rx="2"/><text class="nt" x="194" y="64" text-anchor="middle">Estimate</text><text class="nm" x="194" y="76" text-anchor="middle">OLS fit</text><path class="edge" d="M242 66 H278" marker-end="url(#a)"/><rect class="node" x="278" y="48" width="110" height="36" rx="2"/><text class="nt" x="333" y="64" text-anchor="middle">Check residuals</text><text class="nm" x="333" y="76" text-anchor="middle">5 assumptions</text><path class="edge edge-n" d="M333 48 V20 H180 V48" marker-end="url(#m)"/><text class="el" x="256" y="15" text-anchor="middle">violated &#8594; respecify</text><path class="edge edge-y" d="M388 66 H424" marker-end="url(#g)"/><rect class="node" x="424" y="48" width="96" height="36" rx="2"/><text class="nt" x="472" y="64" text-anchor="middle">Goodness of fit</text><text class="nm" x="472" y="76" text-anchor="middle">R&#178;, AIC, BIC</text><path class="edge" d="M520 66 H556" marker-end="url(#a)"/><rect class="node-c" x="556" y="48" width="130" height="36" rx="2"/><text class="nt" x="621" y="64" text-anchor="middle">Use for inference</text><text class="nm" x="621" y="76" text-anchor="middle">or prediction</text><text class="el" x="333" y="100" text-anchor="middle">this loop is where most marks are lost</text><defs><marker id="a" viewBox="0 0 8 8" refX="7" refY="4" markerWidth="6" markerHeight="6" orient="auto"><path d="M0 0 L8 4 L0 8 z" fill="var(--faint)"/></marker><marker id="g" viewBox="0 0 8 8" refX="7" refY="4" markerWidth="6" markerHeight="6" orient="auto"><path d="M0 0 L8 4 L0 8 z" fill="var(--green)"/></marker><marker id="m" viewBox="0 0 8 8" refX="7" refY="4" markerWidth="6" markerHeight="6" orient="auto"><path d="M0 0 L8 4 L0 8 z" fill="var(--amber)"/></marker><marker id="c" viewBox="0 0 8 8" refX="7" refY="4" markerWidth="6" markerHeight="6" orient="auto"><path d="M0 0 L8 4 L0 8 z" fill="var(--cyan)"/></marker></defs>','The residual check is a loop, not a step. A model that fails an assumption test goes back to specification &mdash; you do not proceed to interpretation and note the problem afterwards.',ARRAY['QM.LM1.a']::text[],'generated'),
